import type { HTMLAttributes, InputHTMLAttributes } from "react";

export function InputGroup({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-flex co-h-10 co-w-full co-items-center co-overflow-hidden co-rounded-md co-border co-border-black/20 co-bg-white focus-within:co-ring-2 ${className}`.trim()} {...props} />; }
export function InputGroupAddon({ className = "", ...props }: HTMLAttributes<HTMLSpanElement>) { return <span className={`co-flex co-h-full co-items-center co-bg-black/5 co-px-3 co-text-sm co-text-black/55 ${className}`.trim()} {...props} />; }
export function InputGroupInput({ className = "", ...props }: InputHTMLAttributes<HTMLInputElement>) { return <input className={`co-h-full co-min-w-0 co-flex-1 co-border-0 co-bg-transparent co-px-3 co-text-sm co-outline-none ${className}`.trim()} {...props} />; }
